-- BEGIN SOURCE supabase/migrations/20260110230052_45eeb5a2-0eca-4745-8f24-631876f34014.sql
-- Full source SHA-256: b350ae72f5c3fea47c19792cef6008954f4524665793ec1b9a387bc6d772f4b3
-- Create enum for roles
CREATE TYPE public.app_role AS ENUM ('admin', 'moderator', 'user');

-- Create user_roles table
CREATE TABLE public.user_roles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,
    role app_role NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
    UNIQUE (user_id, role)
);

-- Enable RLS
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;

-- Create security definer function to check roles (prevents recursive RLS issues)
CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles
    WHERE user_id = _user_id
      AND role = _role
  )
$$;

-- RLS Policies for user_roles
CREATE POLICY "Users can view their own roles"
ON public.user_roles
FOR SELECT
USING (auth.uid() = user_id);

CREATE POLICY "Admins can view all roles"
ON public.user_roles
FOR SELECT
USING (public.has_role(auth.uid(), 'admin'));

CREATE POLICY "Admins can manage roles"
ON public.user_roles
FOR ALL
USING (public.has_role(auth.uid(), 'admin'));
-- END SOURCE supabase/migrations/20260110230052_45eeb5a2-0eca-4745-8f24-631876f34014.sql

-- BEGIN SOURCE supabase/migrations/20260710290000_kumbu_purchases.sql
-- Full source SHA-256: eed5215b6c4a74597c6b3c09ae91e16437aa5a8e4c129a96af8d752dfbcce61d
create table if not exists public.kumbu_purchases (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  kumbu         int  not null,
  amount_kwanza int  not null,
  provider      text not null default 'appypay',
  method        text,                                -- 'GPO' | 'REF'
  status        text not null default 'pending',     -- pending | paid | failed
  provider_ref  text,
  merchant_ref  text,
  created_at    timestamptz not null default now(),
  fulfilled_at  timestamptz
);
create index if not exists kumbu_purchases_user_idx on public.kumbu_purchases (user_id, status);

alter table public.kumbu_purchases enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename='kumbu_purchases' and policyname='own read') then
    create policy "own read" on public.kumbu_purchases for select using (auth.uid() = user_id);
  end if;
end $$;
-- END SOURCE supabase/migrations/20260710290000_kumbu_purchases.sql

-- Harness-only ACLs. Profile editing, signup, social lookup and role management
-- screens are outside this exercise. Only owner reads are exposed to clients.
-- Wallet SECURITY DEFINER functions still read the real tables and real roles.
alter table public.profiles enable row level security;
create policy harness_profile_owner_read on public.profiles
  for select to authenticated using (id = auth.uid());
revoke all on public.profiles, public.user_roles, public.kumbu_purchases
  from public, anon, authenticated, service_role;
grant select on public.profiles, public.user_roles, public.kumbu_purchases to authenticated;
revoke all on function public.has_role(uuid, public.app_role) from public, anon;
grant execute on function public.has_role(uuid, public.app_role) to authenticated, service_role;

