-- records this fixture only; it does not claim full application compatibility.
create schema massa_test_harness;
revoke all on schema massa_test_harness from public, anon, authenticated, service_role;
create table massa_test_harness.installation (
  singleton boolean primary key default true check (singleton),
  target_project text not null check (target_project = 'kvnbqqektpkeouyepyor'),
  source_commit text not null,
  created_at timestamptz not null default now()
);
alter table massa_test_harness.installation enable row level security;
revoke all on massa_test_harness.installation from public, anon, authenticated, service_role;
